import{_ as o,o as t,c as i,a2 as d}from"./chunks/framework.CdvW4CUT.js";const y=JSON.parse('{"title":"Processor Compile-Time Bytecode Transform & Setup","description":"","frontmatter":{},"headers":[],"relativePath":"en/1.21.11/sync/processor-and-network.md","filePath":"en/1.21.11/sync/processor-and-network.md"}'),s={name:"en/1.21.11/sync/processor-and-network.md"};function a(n,e,c,r,l,p){return t(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="processor-compile-time-bytecode-transform-setup" tabindex="-1">Processor Compile-Time Bytecode Transform &amp; Setup <a class="header-anchor" href="#processor-compile-time-bytecode-transform-setup" aria-label="Permalink to &quot;Processor Compile-Time Bytecode Transform &amp; Setup&quot;">​</a></h1><p>To provide a low-boilerplate experience for <code>@Sync</code> and <code>@LazySync</code>, <code>module.sync</code> splits out an independent class-loading transformer/processor subproject <code>anvillib-sync-processor-neoforge-1.21.11</code>, working alongside NeoForge network registration and cross-side lookup utility <code>SideUtil</code>.</p><h2 id="gradle-setup-notes" tabindex="-1">Gradle Setup Notes <a class="header-anchor" href="#gradle-setup-notes" aria-label="Permalink to &quot;Gradle Setup Notes&quot;">​</a></h2><p>If your mod depends directly on full <code>anvillib</code> (or standalone <code>module.sync</code> in dev), note the sync processor and base module dependencies:</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    implementation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;dev.anvilcraft.lib:anvillib-sync-neoforge-1.21.11:&lt;version&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // Processor and related runtime modules (codec / network / util) are included via transitive deps / JarJar;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // If splitting modules or enabling compile-time processor config separately, the artifact is:</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-sync-processor-neoforge-1.21.11</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-codec-neoforge-1.21.11</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-network-neoforge-1.21.11</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // dev.anvilcraft.lib:anvillib-util-neoforge-1.21.11</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="class-loading-transformation-flow-processor" tabindex="-1">Class-Loading Transformation Flow (<code>processor</code>) <a class="header-anchor" href="#class-loading-transformation-flow-processor" aria-label="Permalink to &quot;Class-Loading Transformation Flow (`processor`)&quot;">​</a></h2><p>Submodule <code>module.sync/processor</code> enhances classes with <code>@Sync</code> features in the build/load pipeline via NeoForge&#39;s <code>ClassProcessor</code> SPI (<code>SyncClassProcessor</code>):</p><ol><li><strong><code>SyncTargetIndex</code></strong>: Collects index metadata for all <code>@Sync</code> and <code>@LazySync</code> targets prior to transform/load so <code>SyncConfigManager.compileContent()</code> can build tables quickly at runtime.</li><li><strong><code>SyncClassProcessor</code> &amp; <code>SyncBytecodeInjector</code></strong>: Weaves field write interception and access hooks into target fields in the transform pipeline so mutations automatically trigger dirty updates and sync encoding.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Prefer primitives, common vanilla types (<code>BlockPos</code>, <code>Identifier</code>, <code>ItemStack</code>, <code>CompoundTag</code>, etc.), or types with preset serializers in <code>CodecUtil</code> / <code>StreamCodecUtil</code> for <code>@LazySync</code> fields to get zero-config auto-encoding.</p></div><h2 id="network-protocol-cross-side-helpers-anvillibsyncnetwork-sideutil" tabindex="-1">Network Protocol &amp; Cross-Side Helpers: <code>AnvilLibSyncNetwork</code> &amp; <code>SideUtil</code> <a class="header-anchor" href="#network-protocol-cross-side-helpers-anvillibsyncnetwork-sideutil" aria-label="Permalink to &quot;Network Protocol &amp; Cross-Side Helpers: `AnvilLibSyncNetwork` &amp; `SideUtil`&quot;">​</a></h2><h3 id="packet-payloads-overview" tabindex="-1">Packet Payloads Overview <a class="header-anchor" href="#packet-payloads-overview" aria-label="Permalink to &quot;Packet Payloads Overview&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Payload Class</th><th>Channel ID</th><th>Flow &amp; Responsibility</th></tr></thead><tbody><tr><td><code>SyncConfigurationPayload</code></td><td><code>anvillib_sync:sync_config</code></td><td><code>S2C</code> (Configuration phase): sends server <code>SyncConfigManager</code>&#39;s <code>Map&lt;Integer, String&gt;</code> field ID map</td></tr><tr><td><code>SyncConfigurationFinishPayload</code></td><td><code>anvillib_sync:sync_config_finish</code></td><td><code>C2S</code> (Configuration phase): client confirms map load completion to advance connection</td></tr><tr><td><code>SyncPayload</code></td><td><code>anvillib_sync:sync</code></td><td>Bidirectional (<code>IBidirectionalPacket</code>): immediate single-field <code>SyncProxy</code> update packet</td></tr><tr><td><code>LazySyncPayload</code></td><td><code>anvillib_sync:lazy_sync</code></td><td>Bidirectional (<code>IBidirectionalPacket</code>): incremental sync packet grouping all modified <code>List&lt;FieldChange&gt;</code> for an object in one tick</td></tr></tbody></table><p>All network handlers are registered uniformly by <code>AnvilLibSyncNetwork.register(RegisterPayloadHandlersEvent)</code> under protocol version <code>&quot;1&quot;</code>.</p><h3 id="sideutil-cross-side-send-target-resolution-utilities" tabindex="-1"><code>SideUtil</code> Cross-Side Send &amp; Target Resolution Utilities <a class="header-anchor" href="#sideutil-cross-side-send-target-resolution-utilities" aria-label="Permalink to &quot;`SideUtil` Cross-Side Send &amp; Target Resolution Utilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method Signature</th><th>Return Type</th><th>Description</th></tr></thead><tbody><tr><td><code>SideUtil.isServer()</code></td><td><code>boolean</code></td><td>Determines whether currently running on the logical server thread based on <code>FMLLoader.getCurrent().getDist()</code> and <code>LogicalSide</code></td></tr><tr><td><code>SideUtil.registryAccess()</code></td><td><code>@Nullable RegistryAccess</code></td><td>Safely obtains the active <code>RegistryAccess</code> (<code>ServerLifecycleHooks.getCurrentServer()</code> on server, <code>Minecraft.getInstance().level</code> on client)</td></tr><tr><td><code>SideUtil.entityFinder(IPayloadContext context, UUID uuid)</code></td><td><code>@Nullable Entity</code></td><td>Looks up the entity with <code>uuid</code> in the dimension corresponding to the receiving logical side</td></tr><tr><td><code>SideUtil.blockEntityFinder(IPayloadContext context, BlockPos blockPos)</code></td><td><code>@Nullable BlockEntity</code></td><td>Locates the <code>BlockEntity</code> at <code>blockPos</code> in the dimension associated with this packet</td></tr><tr><td><code>SideUtil.createFriendlyByteBuf(ByteBuf byteBuf)</code></td><td><code>FriendlyByteBuf</code> / <code>RegistryFriendlyByteBuf</code></td><td>Wraps a buffer with <code>RegistryAccess</code> when encoding requires registry context</td></tr><tr><td><code>SideUtil.send(T target, SyncProxy&lt;?&gt; proxy, ...)</code> / <code>serverSend(...)</code> / <code>clientSend(...)</code></td><td><code>void</code></td><td>Automatically routes incremental sync packets to players tracking the entity/chunk or back to the server</td></tr></tbody></table>',15)])])}const u=o(s,[["render",a]]);export{y as __pageData,u as default};
